function elo(data) {
  // Find the two players with the fewest matches.
  let minMatches = Number.MAX_SAFE_INTEGER;
  let Player1 = null;
  let Player2 = null;
  for (let player of data) {
    if (player.Matches < minMatches) {
      minMatches = player.Matches;
      Player1 = player;
      Player2 = data.find(p => p !== Player1);
    }
  }
}'}]

